#!/usr/bin/env node
/**
 * One-off migration: add `department` + `phase` + `reportsTo` + `role`
 * fields to every agent .md frontmatter, pulled from registry.json.
 *
 * Idempotent — safe to re-run.
 *
 * Usage: node ~/.claude/org/scripts/migrate-frontmatter.js
 */

const fs = require('fs');
const path = require('path');
const os = require('os');

// Load gray-matter from Polyglot's node_modules (it's always installed there)
const polyglotNm = '/Users/yashbaldha/Desktop/Boldteq App/Polyglot/node_modules';
const matter = require(path.join(polyglotNm, 'gray-matter'));

const AGENTS_DIR = path.join(os.homedir(), '.claude', 'agents');
const REGISTRY_PATH = path.join(os.homedir(), '.claude', 'org', 'registry.json');

function main() {
  if (!fs.existsSync(REGISTRY_PATH)) {
    console.error('registry.json not found at', REGISTRY_PATH);
    process.exit(1);
  }
  const registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf-8'));
  const files = fs.readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md'));

  let updated = 0;
  let skipped = 0;
  const missing = [];

  for (const file of files) {
    const filename = file.replace(/\.md$/, '');
    if (filename.startsWith('audit-')) { skipped++; continue; }

    const record = registry.agents?.[filename];
    if (!record) {
      missing.push(filename);
      skipped++;
      continue;
    }

    const filePath = path.join(AGENTS_DIR, file);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const parsed = matter(raw);
    const fm = parsed.data || {};

    const nextFm = {
      ...fm,
      department: record.department,
      phase: record.phase,
      reportsTo: record.reportsTo,
      title: record.title,
      tier: record.tier,
    };
    if (record.role) nextFm.role = record.role;

    // Skip if nothing changed
    const changed =
      fm.department !== nextFm.department ||
      fm.phase !== nextFm.phase ||
      fm.reportsTo !== nextFm.reportsTo ||
      fm.title !== nextFm.title ||
      fm.tier !== nextFm.tier ||
      (record.role && fm.role !== nextFm.role);

    if (!changed) { skipped++; continue; }

    const next = matter.stringify(parsed.content, nextFm);
    fs.writeFileSync(filePath, next);
    updated++;
    console.log(`  ✓ ${filename}: ${record.department} / ${record.phase || '—'} / ${record.title}`);
  }

  console.log(`\nDone. Updated: ${updated}, skipped: ${skipped}`);
  if (missing.length) {
    console.log(`No registry record for: ${missing.join(', ')}`);
  }
}

main();

