// ── HR routes ────────────────────────────────────────────────────────────────

// Helper — read the last N hours of agent runs for Witness sweep
function loadRecentAgentRuns(hours = 24) {
  try {
    const runsPath = path.join(__dirname, '..', 'agent-runs.json');
    if (!fs.existsSync(runsPath)) return [];
    const raw = JSON.parse(fs.readFileSync(runsPath, 'utf-8'));
    if (!Array.isArray(raw)) return [];
    const cutoff = Date.now() - hours * 60 * 60 * 1000;
    return raw.filter((r) => new Date(r.timestamp).getTime() >= cutoff);
  } catch {
    return [];
  }
}

// Full registry (for HR page)
app.get('/api/hr/registry', rateLimit('read'), (req, res) => {
  try {
    res.json(hr.getRegistry(org));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Individual agent profile (with direct reports)
app.get('/api/hr/agent/:id', rateLimit('read'), (req, res) => {
  try {
    const profile = hr.getAgentProfile(org, req.params.id);
    if (!profile) return res.status(404).json({ error: 'Not found' });
    res.json(profile);
  } catch (err) {
    res.status(500).json({ error: err.message });
