// ── HR routes ────────────────────────────────────────────────────────────────

// Helper — read the last N hours of agent runs for Witness sweep
function loadRecentAgentRuns(hours = 24) {
  try {
    const runsPath = path.join(__dirname, '..', 'agent-runs.json');
    if (!fs.existsSync(runsPath)) return [];
    const raw = JSON.parse(fs.readFileSync(runsPath, 'utf-8'));
    if (!Array.isArray(raw)) return [];
    const cutoff = Date.now() - hours * 60 * 60 * 1000;
    return raw.filter((r) => new Date(r.timestamp).getTime() >= cutoff);
  } catch {
    return [];
  }
}

