          member.status === 'pip' ? 'bg-red-500/15 text-red-400' :
          'bg-zinc-500/10 text-zinc-500'
        }`}
      >
        {member.status}
      </span>
    )}
  </div>
)}

toolUseResult.newString:
{/* Row 3: level title + YoE + status */}
{member.level != null && (
  <div className="flex items-center gap-1.5 mt-1 min-w-0">
    <span
      className={`text-[9px] font-bold uppercase tracking-wider truncate ${levelColors(member.level).text}`}
      style={{ flex: '1 1 0%', minWidth: 0 }}
      title={`${member.levelTitle || ''} · ${member.yearsOfExperience ?? 0}y experience`}
    >
      {member.levelTitle}
    </span>
    {member.yearsOfExperience != null && (
      <span className="text-[9px] text-text-muted font-mono shrink-0 whitespace-nowrap">
        · {Math.round(member.yearsOfExperience)}y
      </span>
    )}
    {member.status && member.status !== 'active' && (
      <span
        className={`text-[8px] px-1 py-0.5 rounded font-bold uppercase shrink-0 whitespace-nowrap ${
          member.status === 'probation' ? 'bg-amber-500/15 text-amber-400' :
          member.status === 'pip' ? 'bg-red-500/15 text-red-400' :
          'bg-zinc-500/10 text-zinc-500'
        }`}
      >
        {member.status}
      </span>
    )}
  </div>
)}
